 } public function unique_2d_array_by_key($arr, $key){ $tmp_arr = array(); foreach($arr as $k => $v) { if (in_array($v[$key], $tmp_arr)) { unset($arr[$k]); } else { $tmp_arr[$k] = $v[$key]; } } return $arr; } public function get_header($headers, $label = 'Content-Type') { $pattern = $this->encode_pattern($label); $preg = preg_match_all('/'.$pattern.': (.*)/i', $headers, $match); return $preg ? trim(array_pop($match[1])) : false; } public function get_extension($type) { $type = trim($type); switch ($type) { case 'image/jpeg': $extension = 'jpg'; break; case 'image/png': $extension = 'png'; break; case 'image/gif': $extension = 'gif'; break; case 'video/mp4': $extension = 'mp4'; break; case 'audio/mpeg': $extension = 'mp3'; break; default: $extension = preg_replace('/^.*\//i', '', $type); break; } return $extension; } public function getStrFromArray($array, $string) { foreach ($array as $arr) { if (is_array($arr)) $string = array_merge($string, $this->getStrFromArray($arr, $string)); else $string[] = $arr; } return $string; } public function get_attrs_str($attrs) { $getStrFromArray = function() { global $getStrFromArray; }; $resutls = array(); if (!empty($attrs)) foreach ($attrs as $property => $value) { if (is_array($value)) $value = implode(' ', $this->getStrFromArray($value, array())); $resutls[] = $property .= '="'.$value.'"'; } return implode(' ', $resutls); } public function rgb2hex($rgb) { $hex = "#"; $hex .= str_pad(dechex($rgb[0]), 2, "0", STR_PAD_LEFT); $hex .= str_pad(dechex($rgb[1]), 2, "0", STR_PAD_LEFT); $hex .= str_pad(dechex($rgb[2]), 2, "0", STR_PAD_LEFT); return $hex; } public function hex2rgb($hex) { $hex = str_replace("#", "", $hex); if(strlen($hex) == 3) { $r = hexdec(substr($hex,0,1).substr($hex,0,1)); $g = hexdec(substr($hex,1,1).substr($hex,1,1)); $b = hexdec(substr($hex,2,1).substr($hex,2,1)); } else { $r = hexdec(substr($hex,0,2)); $g = hexdec(substr($hex,2,2)); $b = hexdec(substr($hex,4,2)); } return array($r, $g, $b); } public function isAnimatedGif($str, $type='filepath') { if($type=='filepath'){ $fp = fopen($str,'rb'); $filecontent = fread($fp,filesize($str)); fclose($fp); } else{ $filecontent = $str; } return strpos($filecontent,chr(0x21).chr(0xff).chr(0x0b).'NETSCAPE2.0')===FALSE?0:1; } public function getFileType($file, $mode='filetype') { $bin = substr($file,0,2); $strInfo = @unpack("C2chars", $bin); $typeCode = intval($strInfo['chars1'].$strInfo['chars2']); switch ($typeCode) { case 7790: $fileType = 'exe'; return false; case 7784: $fileType = 'midi'; return false; case 8297: $fileType = 'rar'; return false; case 255216: $fileType = 'jpg'; $mime = 'image/jpeg'; return $mode=='filetype' ? $fileType : $mime; case 7173: $fileType = 'gif'; $mime = 'image/gif'; return $mode=='filetype' ? $fileType : $mime; case 6677: $fileType = 'bmp'; $mime = 'image/bmp'; return $mode=='filetype' ? $fileType : $mime; case 13780: $fileType = 'png'; $mime = 'image/png'; return $mode=='filetype' ? $fileType : $mime; default: return false; } } public function the_switcher($args, $echo=true) { extract($args); $on = filter_var($value, FILTER_VALIDATE_BOOLEAN) ? ' checked' : ''; $codes = '<div class="qqworld-collector onoffswitch">
