		</div>'; if ($echo) print $codes; else return $codes; } public function includes_lib($type = null) { switch ($type) { case 'pinyin': if (!class_exists('Overtrue\\Pinyin\\Pinyin')) { $files = array('DictLoaderInterface', 'FileDictLoader', 'Pinyin'); foreach ($files as $filename) { require QQWORLD_COLLECTOR_DIR . 'lib' . DIRECTORY_SEPARATOR . 'overtrue_pinyin' . DIRECTORY_SEPARATOR . 'src' . DIRECTORY_SEPARATOR . $filename . '.php'; } } break; } } public function num_cpus() { $numCpus = 1; if (is_file('/proc/cpuinfo')) { $cpuinfo = file_get_contents('/proc/cpuinfo'); preg_match_all('/core id\s*:\s(\d*)/i', $cpuinfo, $matches); $numCpus = count(array_unique($matches[1])); preg_match_all('/^processor/m', $cpuinfo, $matches); $numThreads = count($matches[0]); } else if ('WIN' == strtoupper(substr(PHP_OS, 0, 3))) { $process = @popen('wmic cpu get NumberOfCores', 'rb'); if ($process) { fgets($process); $numCpus = intval(fgets($process)); pclose($process); } $process = @popen('wmic cpu get NumberOfLogicalProcessors', 'rb'); if ($process) { fgets($process); $numThreads = intval(fgets($process)); pclose($process); } } else { $process = @popen('sysctl -a', 'rb'); if ($process) { $output = stream_get_contents($process); preg_match('/hw.ncpu: (\d+)/', $output, $matches); if ($matches) { $numCpus = intval($matches[1][0]); } pclose($process); $numThreads = $numCpus; } } return array($numCpus, $numThreads); } public function get_all_thumb_file_full_path($attachment_id, $fullsize_path) { $imagedata = wp_get_attachment_metadata( $attachment_id ); $file_paths = array(); foreach ($imagedata['sizes'] as $size => $thumb) { if ( !empty($thumb['file']) && ($thumbfile = str_replace(basename($fullsize_path), $thumb['file'], $fullsize_path)) && file_exists($thumbfile) ) { $file_paths[$size] = $thumbfile; } } return $file_paths; } public function formatBytes($size, $precision=2) { $base = log($size, 1024); $suffixes = array('B', 'KB', 'MB', 'GB', 'TB'); return isset($suffixes[floor($base)]) ? round(pow(1024, $base - floor($base)), $precision) . $suffixes[floor($base)] : ''; } } ?>